// ─── File: src/test/java/com/bank/startrun/StartVsRunTest.java ───
package com.bank.startrun;

import org.junit.jupiter.api.Test;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.atomic.AtomicReference;
import static org.assertj.core.api.Assertions.*;

class StartVsRunTest {

    // ═══ start() runs on NEW thread ═══
    @Test
    void start_runsOnNewThread() throws InterruptedException {
        AtomicReference<String> threadName = new AtomicReference<>();
        Thread t = new Thread(() -> threadName.set(Thread.currentThread().getName()));
        t.start();
        t.join();

        assertThat(threadName.get()).isNotEqualTo("main");  // different thread!
        assertThat(threadName.get()).startsWith("Thread");   // "Thread-0" or similar
    }

    // ═══ run() runs on CURRENT thread ═══
    @Test
    void run_runsOnCurrentThread() {
        AtomicReference<String> threadName = new AtomicReference<>();
        Thread t = new Thread(() -> threadName.set(Thread.currentThread().getName()));
        t.run();  // direct call — no new thread!

        assertThat(threadName.get()).isEqualTo(Thread.currentThread().getName());  // SAME thread!
    }

    // ═══ start() enables PARALLEL execution ═══
    @Test
    void start_isParallel() throws InterruptedException {
        long startTime = System.currentTimeMillis();
        CountDownLatch latch = new CountDownLatch(3);

        for (int i = 0; i < 3; i++) {
            new Thread(() -> {
                try { Thread.sleep(100); } catch (InterruptedException e) { }
                latch.countDown();
            }).start();  // PARALLEL!
        }
        latch.await();
        long elapsed = System.currentTimeMillis() - startTime;

        assertThat(elapsed).isLessThan(300);  // ~100ms (parallel), not 300ms!
    }

    // ═══ run() is SEQUENTIAL ═══
    @Test
    void run_isSequential() {
        long startTime = System.currentTimeMillis();

        for (int i = 0; i < 3; i++) {
            new Thread(() -> {
                try { Thread.sleep(100); } catch (InterruptedException e) { }
            }).run();  // SEQUENTIAL! Each waits for the previous!
        }
        long elapsed = System.currentTimeMillis() - startTime;

        assertThat(elapsed).isGreaterThanOrEqualTo(300);  // ~300ms (sequential)!
    }

    // ═══ start() cannot be called twice ═══
    @Test
    void start_cannotBeCalledTwice() throws InterruptedException {
        Thread t = new Thread(() -> {});
        t.start();
        t.join();
        assertThatThrownBy(t::start)
            .isInstanceOf(IllegalThreadStateException.class);
    }
}
